BEGIN READ ONLY; SET LOCAL statement_timeout='20s';
SELECT jsonb_build_object('captured_at',clock_timestamp(),'version',version(),'database_bytes',pg_database_size(current_database()),'inventory',(SELECT jsonb_build_object('total',count(*),'non_deleted',count(*) FILTER(WHERE deleted_at IS NULL),'public',count(*) FILTER(WHERE deleted_at IS NULL AND hidden=false),'hidden',count(*) FILTER(WHERE deleted_at IS NULL AND hidden IS DISTINCT FROM false),'missing_seating',count(*) FILTER(WHERE deleted_at IS NULL AND seating_area IS NULL)) FROM public.venues),'series',(SELECT jsonb_build_object('rows',count(*),'with_input_payload',count(*) FILTER(WHERE input_payload IS NOT NULL),'oldest_date',min(stockholm_date),'newest_date',max(stockholm_date)) FROM public.venue_sun_geometry_series),'relations',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'heap_main_bytes',pg_relation_size(c.oid),'table_including_toast_bytes',pg_table_size(c.oid),'indexes_bytes',pg_indexes_size(c.oid),'total_bytes',pg_total_relation_size(c.oid)) ORDER BY n.nspname,c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind IN ('r','m') AND n.nspname NOT IN ('pg_catalog','information_schema') AND n.nspname NOT LIKE 'pg_toast%')) AS capture; COMMIT;
